export function waveHeight(x,z,t,strength=1){return strength*(Math.sin(x*.065+z*.10+t*.9)*.12+Math.sin(x*.14-z*.045+t*1.25)*.065+Math.sin(z*.32+t*1.7)*.025);}
export function depthAt(x,z){return Math.max(3.8,4.5+Math.min(200,Math.max(0,-z-70))*.06+Math.max(0,-z-270)*.025+Math.sin(x*.025)*1.6+Math.cos(z*.018)*1.1);}
